WITH remaining_keys AS (SELECT segment, country FROM customers EXCEPT SELECT segment, country FROM customers WHERE city IS NOT NULL), reconciled AS (SELECT s.* FROM customers s INNER JOIN remaining_keys k ON s.segment = k.segment AND s.country = k.country) SELECT name, city, signup_date, age, CASE WHEN name RLIKE '^(FRANK MILLER|Kanya Srisuk)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS name_zone FROM reconciled ORDER BY name_zone DESC NULLS LAST;
